BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — Dissolution clause requirement
(3, 'Tax-Exempt Organizations', 'What must an organization''s governing documents include to satisfy the organizational test for Section 501(c)(3) status?', '["A provision requiring annual audits by an independent CPA firm", "A statement that the organization will operate for at least 10 years", "A dissolution clause directing assets to another exempt organization or the government upon dissolution", "A clause requiring unanimous board approval for all expenditures"]'::jsonb, 2, 'Under IRC Section 501(c)(3), the organizational test requires governing documents to limit purposes to exempt purposes and include a dissolution clause directing remaining assets to another 501(c)(3) organization or a government entity. Unlike choice A, annual audits are not part of the organizational test — they are a governance best practice, not a statutory requirement.', 'easy', 1),

-- Q2: medium / L2 — Public charity one-third support test
(3, 'Tax-Exempt Organizations', 'Helping Hands Inc., a 501(c)(3) organization, receives $900,000 in total support over a four-year period. Of that amount, $250,000 comes from government grants and public contributions, with the remaining $650,000 from investment income and a single large bequest. Helping Hands claims public charity status under Section 509(a)(1). Does it qualify?', '["Yes, because it received more than $200,000 from public sources", "No, because public support of $250,000 is less than one-third of total support of $900,000", "Yes, because government grants automatically satisfy the public support test regardless of amount", "No, because organizations receiving investment income cannot be public charities"]'::jsonb, 1, 'Under IRC Section 509(a)(1), an organization qualifies as a public charity if it receives at least one-third of its total support from governmental sources and public contributions. Helping Hands received only $250,000 / $900,000 (27.8%), falling below the one-third threshold. Unlike choice A suggests, there is no fixed dollar threshold — the test is based on the proportion of public support to total support.', 'medium', 2),

-- Q3: medium / L2 — Supporting organizations (509(a)(3))
(3, 'Tax-Exempt Organizations', 'Friends of City Library is organized and operated exclusively to raise funds for the City Public Library, a 501(c)(3) public charity. Friends of City Library does not receive broad public support and would otherwise be classified as a private foundation. Under what provision can it maintain public charity status?', '["Section 509(a)(1), because it raises funds for charitable purposes", "Section 509(a)(4), because it tests for public safety", "Section 170(b)(1)(A)(vi), because it is a community foundation", "Section 509(a)(3), as a supporting organization operated exclusively to support a public charity"]'::jsonb, 3, 'Under IRC Section 509(a)(3), an organization operated exclusively to support one or more public charities qualifies as a supporting organization and is classified as a public charity rather than a private foundation. Unlike Section 509(a)(1), which requires broad public support, Section 509(a)(3) focuses on the organization''s operational relationship with the supported public charity.', 'medium', 2),

-- Q4: hard / L4 — Controlled entity UBIT and personal property rents
(3, 'Tax-Exempt Organizations', 'Education Alliance, a 501(c)(3) organization, owns 100% of Training Corp., a taxable subsidiary. Training Corp. pays Education Alliance $120,000 annually in rent for office space and equipment. The fair market rental value is $80,000 for the office space and $15,000 for the equipment. Analyze how the controlled entity rules and the personal property rent modification interact to determine the UBIT treatment of these payments.', '["The excess rent above fair market value ($25,000) is treated as UBIT under the controlled entity rules, and the personal property component must be evaluated separately", "All $120,000 is excluded from UBIT because rents from real and personal property are passive income", "Only the $15,000 equipment rent is UBIT because personal property rents are always taxable", "The entire $120,000 is UBIT because any rental from a controlled subsidiary is automatically unrelated business income"]'::jsonb, 0, 'Under IRC Section 512(b)(13), rent received from a controlled entity (80%+ ownership) is treated as UBIT to the extent it exceeds fair market value. Here, total FMV is $95,000, so $25,000 of excess rent is UBIT. Unlike choice D assumes, the controlled entity rule does not tax all payments — only the amount exceeding FMV. The personal property rent at FMV requires separate analysis under the 10% incidental rule for mixed leases.', 'hard', 4),

-- Q5: medium / L3 — Convenience exclusion application
(3, 'Tax-Exempt Organizations', 'State University, a 501(c)(3) institution, operates a campus cafeteria open only to enrolled students and faculty during academic hours. The cafeteria generates $400,000 in annual revenue. The university also operates a catering service available to the general public, earning $150,000 annually. Apply the UBIT convenience exclusion to determine which revenue streams are excluded.', '["Both the cafeteria and catering revenues are excluded because they are operated by a university", "Neither revenue stream is excluded because food service is always an unrelated trade or business", "The cafeteria revenue is excluded under the convenience exception, but the catering revenue for the public is not excluded", "The catering revenue is excluded because it generates less than $500,000, but the cafeteria revenue is taxable"]'::jsonb, 2, 'Under IRC Section 513(a)(2), an activity conducted primarily for the convenience of members, students, patients, or employees is excluded from UBIT. The campus cafeteria serving only students and faculty qualifies for this exclusion. The public catering service does not, because it serves the general public rather than the university''s own community. Unlike choice A, the exemption depends on who is served, not who operates the activity.', 'medium', 3),

-- Q6: medium / L3 — Form 990 vs 990-EZ threshold distinction
(3, 'Tax-Exempt Organizations', 'Neighborhood Outreach, a 501(c)(3) public charity, has gross receipts of $180,000 and total assets of $450,000 for the current tax year. The organization''s treasurer is determining which annual information return to file with the IRS. Apply the filing thresholds to determine the correct form.', '["Form 990-N (e-Postcard), because gross receipts are under $200,000", "Form 990-EZ, because gross receipts are under $200,000 and total assets are under $500,000", "Form 990, because total assets exceed $200,000", "No filing is required because the organization is a public charity"]'::jsonb, 1, 'Under IRC Section 6033, Form 990-EZ may be filed when gross receipts are less than $200,000 AND total assets are less than $500,000. Neighborhood Outreach meets both thresholds ($180,000 < $200,000 and $450,000 < $500,000). Unlike choice A, Form 990-N is only available for organizations with gross receipts of $50,000 or less — the $180,000 in receipts far exceeds that threshold.', 'medium', 3),

-- Q7: easy / L1 — Exempt purposes enumerated
(3, 'Tax-Exempt Organizations', 'Which of the following is a recognized exempt purpose under Section 501(c)(3)?', '["Operating a commercial retail business", "Generating investment returns for shareholders", "Lobbying for political candidates", "Fostering national or international amateur sports competition"]'::jsonb, 3, 'Under IRC Section 501(c)(3), fostering national or international amateur sports competition is one of the specifically enumerated exempt purposes. Unlike choice C, political campaign activity is absolutely prohibited — it is not an exempt purpose but rather a disqualifying activity that can result in revocation of tax-exempt status.', 'easy', 1),

-- Q8: medium / L2 — Section 501(h) expenditure test election
(3, 'Tax-Exempt Organizations', 'Clean Water Alliance, a 501(c)(3) public charity with annual exempt purpose expenditures of $500,000, elects the Section 501(h) expenditure test to establish a safe harbor for its lobbying activities. Under this election, what is the maximum amount the organization may spend on lobbying without jeopardizing its exempt status?', '["$100,000, calculated as 20% of the first $500,000 of exempt purpose expenditures", "$500,000, because the 501(h) election removes all lobbying restrictions", "$50,000, calculated as 10% of total expenditures", "$25,000, the flat-dollar ceiling for all electing organizations"]'::jsonb, 0, 'Under IRC Section 501(h), the lobbying nontaxable amount is calculated on a sliding scale: 20% of the first $500,000 of exempt purpose expenditures. For an organization with $500,000 in expenditures, the maximum lobbying amount is $100,000. Unlike choice B, the 501(h) election does not eliminate lobbying limits — it replaces the vague ''substantial part'' test with specific dollar thresholds.', 'medium', 2),

-- Q9: medium / L3 — Research exclusion from UBIT
(3, 'Tax-Exempt Organizations', 'Greenfield University, a 501(c)(3) institution, operates a research laboratory conducting three types of research: (1) $200,000 in contract research for a private pharmaceutical company with results kept proprietary, (2) $150,000 in government-funded research for the Department of Defense, and (3) $100,000 in research whose findings are freely published in academic journals. Apply the UBIT research exclusion to determine which income is excluded.', '["All $450,000 is excluded because universities are exempt from UBIT on all research", "Only the $150,000 government research is excluded; the other $300,000 is subject to UBIT", "The $150,000 government research and $100,000 publicly available research are excluded; the $200,000 proprietary research is subject to UBIT", "None of the research income is excluded because all contract research is unrelated business activity"]'::jsonb, 2, 'Under IRC Section 512(b)(7)-(9), research performed for the U.S. government or research whose results are freely available to the public is excluded from UBIT. The proprietary research for a private company, where results are kept confidential, does not qualify for either exclusion. Unlike choice A, the exclusion is based on the nature of the research and its availability, not the type of institution performing it.', 'medium', 3),

-- Q10: medium / L3 — Late filing penalty calculation
(3, 'Tax-Exempt Organizations', 'Riverside Community Services, a 501(c)(3) with gross receipts of $400,000, files its Form 990 seventy-five days late without reasonable cause. Apply the penalty provisions to determine the amount Riverside owes for the late filing.', '["$750, calculated at $10 per day for 75 days", "$1,500, calculated at $20 per day for 75 days", "$7,500, calculated at $100 per day for 75 days", "$20,000, the fixed penalty for any late Form 990 filing"]'::jsonb, 1, 'Under IRC Section 6652(c)(1)(A), the penalty for failing to file Form 990 is $20 per day for organizations with gross receipts under $1,186,000, up to a maximum of $10,500 or 5% of gross receipts, whichever is less. At $20 x 75 days = $1,500, which is below the cap. Unlike choice C, the $100 per day rate applies only to larger organizations with gross receipts of $1,186,000 or more.', 'medium', 3),

-- Q11: medium / L2 — Rebuttable presumption of reasonableness
(3, 'Tax-Exempt Organizations', 'Midwest Health Foundation, a 501(c)(3), hires a new executive director at an annual salary of $450,000. The independent board members review compensation data from three comparable organizations, document their analysis in board minutes, and vote to approve the salary. Under Section 4958, what is the effect of following these procedures?', '["The compensation is automatically deemed reasonable regardless of the actual amount", "The organization is permanently immune from intermediate sanctions on this transaction", "The IRS is prohibited from auditing the compensation arrangement", "A rebuttable presumption of reasonableness is established, shifting the burden of proof to the IRS"]'::jsonb, 3, 'Under IRC Section 4958 regulations, compensation is presumed reasonable when approved by an independent board using appropriate comparability data with concurrent documentation. This creates a rebuttable presumption, meaning the IRS bears the burden of proving the compensation is excessive. Unlike choice A, the presumption is rebuttable — the IRS can still challenge it with sufficient evidence that the amount exceeds fair market value.', 'medium', 2),

-- Q12: easy / L1 — Form 990-N e-Postcard filing threshold
(3, 'Tax-Exempt Organizations', 'What is the maximum gross receipts threshold for a tax-exempt organization to file Form 990-N (e-Postcard)?', '["$50,000", "$100,000", "$200,000", "$500,000"]'::jsonb, 0, 'Under IRC Section 6033(i), tax-exempt organizations with annual gross receipts normally $50,000 or less may file Form 990-N, an electronic notice containing basic identifying information. Unlike the $200,000 threshold in choice C, which determines eligibility for Form 990-EZ, the e-Postcard is reserved for the smallest exempt organizations.', 'easy', 1),

-- Q13: easy / L1 — Private inurement prohibition
(3, 'Tax-Exempt Organizations', 'What does the private inurement prohibition under Section 501(c)(3) prevent?', '["Tax-exempt organizations from earning any revenue", "Tax-exempt organizations from paying reasonable salaries to employees", "Net earnings of a tax-exempt organization from benefiting any private shareholder or individual", "Tax-exempt organizations from investing in securities or real property"]'::jsonb, 2, 'Under IRC Section 501(c)(3), no part of the net earnings of a tax-exempt organization may inure to the benefit of any private shareholder or individual. This prohibition targets insider enrichment, not legitimate compensation. Unlike choice B, organizations may pay reasonable salaries — the restriction applies to excessive or unjustified benefits flowing to insiders.', 'easy', 1),

-- Q14: medium / L3 — Organization manager tax under Section 4958
(3, 'Tax-Exempt Organizations', 'Lakeside Education Fund, a 501(c)(3), pays its founder an annual consulting fee of $300,000 when comparable services cost $80,000. The board treasurer, who is the founder''s spouse, knowingly approves the arrangement without obtaining comparability data. Apply Section 4958 to determine the excise tax on the board treasurer.', '["$55,000, which is 25% of the excess benefit", "$20,000, which is the statutory maximum for an organization manager who knowingly participates", "$22,000, which is 10% of the excess benefit with no cap", "$44,000, which is 200% of the manager tax"]'::jsonb, 1, 'Under IRC Section 4958(d)(2), an organization manager who knowingly participates in an excess benefit transaction faces a 10% excise tax on the excess benefit, capped at $20,000 per transaction. The excess benefit is $220,000 ($300,000 - $80,000), making the raw 10% calculation $22,000, but the statutory cap limits the tax to $20,000. Unlike choice C, which applies the 10% rate without the cap, Section 4958 imposes a per-transaction ceiling on manager liability.', 'medium', 3),

-- Q15: easy / L2 — Form 990-PF for private foundations
(3, 'Tax-Exempt Organizations', 'The Jefferson Family Foundation, a private foundation with gross receipts of $75,000 and total assets of $2,000,000, asks its accountant which annual information return it must file with the IRS. Which form is required?', '["Form 990-PF, because all private foundations must file this form regardless of size", "Form 990-EZ, because gross receipts are under $200,000", "Form 990-N, because gross receipts are under $200,000", "No filing is required for private foundations with gross receipts under $100,000"]'::jsonb, 0, 'Under IRC Section 6033(a), all private foundations must file Form 990-PF regardless of their size, gross receipts, or total assets. This includes detailed reporting on excise tax computations, grants, and investment activities. Unlike choice B, Form 990-EZ is for public charities meeting size thresholds — private foundations cannot use the simplified forms.', 'easy', 2),

-- Q16: medium / L3 — Bingo games exclusion application
(3, 'Tax-Exempt Organizations', 'Riverside Veterans Post, a 501(c)(3) organization, operates weekly bingo games in a state where commercial bingo is not ordinarily conducted. Volunteers staff the games, and proceeds fund veteran support programs. The post also operates a monthly poker tournament with cash prizes. Apply the UBIT exclusions to determine which activities are excluded.', '["Both bingo and poker are excluded because all games of chance operated by exempt organizations are exempt from UBIT", "Neither activity is excluded because gambling activities are always treated as unrelated business income", "Only the poker tournament is excluded because it is held monthly rather than weekly", "Only the bingo games are excluded under the statutory bingo exclusion; the poker tournament does not qualify"]'::jsonb, 3, 'Under IRC Section 513(f), bingo games are excluded from UBIT when the game is not ordinarily carried on as a commercial basis in the jurisdiction and when state or local law does not prohibit the activity. This exclusion is specific to bingo and does not extend to other games of chance like poker. Unlike choice A, the exclusion is narrowly limited to bingo, not all gambling activities.', 'medium', 3),

-- Q17: medium / L2 — Filing deadline (15th day of 5th month)
(3, 'Tax-Exempt Organizations', 'Hope Community Center, a calendar-year 501(c)(3) organization, is preparing its annual Form 990. The organization''s fiscal year ends on December 31, 2025. By what date must the Form 990 be filed with the IRS?', '["March 15, 2026, the same deadline as corporate tax returns", "April 15, 2026, the same deadline as individual tax returns", "May 15, 2026, the 15th day of the 5th month after the end of the tax year", "June 15, 2026, six months after the end of the fiscal year"]'::jsonb, 2, 'Under IRC Section 6033, Form 990 is due on the 15th day of the 5th month following the end of the organization''s tax year. For a calendar-year organization ending December 31, 2025, the filing deadline is May 15, 2026. Unlike choice A, the March 15 deadline applies to C corporation tax returns (Form 1120), not exempt organization information returns.', 'medium', 2),

-- Q18: medium / L2 — NOL deduction in UBIT computation
(3, 'Tax-Exempt Organizations', 'Heritage Museum, a 501(c)(3), had unrelated business taxable losses of $30,000 in 2024 and $20,000 in 2025. In 2026, the museum has $80,000 in gross unrelated business income and $25,000 in directly connected expenses. How is the net operating loss from prior years treated in computing 2026 UBIT?', '["The $50,000 NOL carryforward reduces 2026 UBI, resulting in $4,000 of taxable income after the $1,000 specific deduction", "Prior-year losses cannot offset current UBIT because exempt organizations do not qualify for NOL deductions", "Only the 2025 loss of $20,000 may be carried forward; the 2024 loss has expired", "The NOL may only offset 50% of current-year UBI, limiting the deduction to $27,500"]'::jsonb, 0, 'Under IRC Section 512(b)(6), net operating losses from unrelated business activities may be carried forward and used to offset future UBI, computed using only UBI items. The $50,000 NOL ($30,000 + $20,000) reduces 2026 net UBI of $55,000 ($80,000 - $25,000) to $5,000, then the $1,000 specific deduction yields $4,000 taxable. Unlike choice B, exempt organizations are expressly permitted NOL deductions computed solely from unrelated business items.', 'medium', 2),

-- Q19: hard / L4 — Private benefit vs private inurement distinction
(3, 'Tax-Exempt Organizations', 'Bright Future Academy, a 501(c)(3) educational organization, hires an external marketing consultant (not a board member, officer, or insider) for $200,000 to redesign its website. The fair market value for comparable services is $60,000. The consultant has no personal relationship with any officer or director. Analyze whether this arrangement constitutes private inurement, private benefit, or neither, and evaluate the potential consequences under Section 501(c)(3).', '["This is private inurement because the consultant received compensation exceeding fair market value from an exempt organization", "This is excessive private benefit but not private inurement, because the consultant is not an insider, and it could threaten exempt status if more than incidental", "This is neither private benefit nor private inurement because the organization received legitimate services in return for the payment", "This triggers intermediate sanctions under Section 4958 because the payment exceeds fair market value by more than 100%"]'::jsonb, 1, 'Under IRC Section 501(c)(3), private inurement applies only to insiders (private shareholders or individuals with a personal stake in the organization). The consultant is an outsider, so private inurement does not apply. However, the excessive payment constitutes private benefit, which can threaten exempt status if it is more than incidental and not furthering exempt purposes. Unlike choice D, Section 4958 intermediate sanctions apply only to disqualified persons, not outside contractors.', 'hard', 4),

-- Q20: medium / L2 — Churches automatic public charity
(3, 'Tax-Exempt Organizations', 'Grace Fellowship Church, a 501(c)(3) religious organization, receives 90% of its funding from a single wealthy donor family and does not receive broad public support. The church''s board is concerned it will be reclassified as a private foundation. How is the church classified under Section 509?', '["As a private foundation, because it fails the one-third public support test", "As a private foundation, because more than 50% of funding comes from a single source", "As a public charity only if it can demonstrate broad community benefit", "As a public charity, because churches are automatically classified as public charities regardless of funding sources"]'::jsonb, 3, 'Under IRC Section 509(a)(1) and Section 170(b)(1)(A)(i), churches are automatically classified as public charities regardless of their funding sources. They are not required to meet the one-third support test that applies to other 501(c)(3) organizations. Unlike choice A, the public support test does not apply to churches, hospitals, or schools, which receive automatic public charity classification.', 'medium', 2),

-- Q21: easy / L1 — Personal property rents in UBIT
(3, 'Tax-Exempt Organizations', 'Under Section 512, how are rents from personal property generally treated for UBIT purposes?', '["Included in unrelated business taxable income unless incidental to a real property lease", "Excluded from UBIT as passive income in all circumstances", "Included only if the personal property has a value exceeding $100,000", "Excluded from UBIT when the rental term is less than one year"]'::jsonb, 0, 'Under IRC Section 512(b)(3), rents from real property are generally excluded from UBIT, but rents from personal property are included unless they are incidental (less than 10% of total rents under the lease) to a real property rental. Unlike choice B, the passive income exclusion for rents specifically carves out personal property rents, which remain taxable.', 'easy', 1),

-- Q22: hard / L4 — Taxable expenditures Section 4945 grants to non-charities
(3, 'Tax-Exempt Organizations', 'The Marshall Education Foundation, a private foundation, makes a $100,000 grant to Civic Action Network, a 501(c)(4) social welfare organization, to fund voter registration drives. The foundation does not exercise expenditure responsibility over the grant and does not verify how the funds are used. Evaluate the tax consequences of this grant under Section 4945, including the excise taxes on both the foundation and any participating foundation managers.', '["No excise tax applies because voter registration is an exempt activity and 501(c)(4) organizations are tax-exempt", "A 10% excise tax on the foundation and 2.5% on the foundation manager, totaling $12,500", "A 20% initial excise tax ($20,000) on the foundation, plus 5% ($5,000) on any foundation manager who knowingly approved the grant", "A 30% excise tax on the undistributed amount because the grant was not made for charitable purposes"]'::jsonb, 2, 'Under IRC Section 4945(d)(4), a grant by a private foundation to a non-501(c)(3) organization is a taxable expenditure unless the foundation exercises expenditure responsibility. The initial tax is 20% of the expenditure on the foundation ($20,000) and 5% on any foundation manager who knowingly approved it ($5,000). Unlike choice A, the tax-exempt status of a 501(c)(4) does not exempt the foundation from expenditure responsibility requirements.', 'hard', 4),

-- Q23: hard / L3 — Self-dealing additional tax for non-correction
(3, 'Tax-Exempt Organizations', 'In 2024, the founder of Parker Arts Foundation (a private foundation) leased office space from the foundation at $2,000 per month. The IRS determines this is a self-dealing transaction under Section 4941 and assesses the initial 10% excise tax. The founder refuses to unwind the lease within the correction period. Apply Section 4941 to determine the additional excise tax for failure to correct.', '["An additional 10% tax on the self-dealer for the second year of the lease", "An additional 200% tax on the amount involved, imposed on the self-dealer", "An additional 50% tax on the foundation manager who approved the lease", "An additional 100% tax on the foundation''s net investment income"]'::jsonb, 1, 'Under IRC Section 4941(b), if a self-dealing transaction is not corrected within the taxable period, an additional excise tax of 200% of the amount involved is imposed on the self-dealer. The correction requires undoing the transaction to the extent possible. Unlike choice C, the additional tax falls on the self-dealer, not the foundation manager — the manager''s additional tax under Section 4941(b)(2) is 50% of the amount involved, capped at $20,000.', 'hard', 3),

-- Q24: medium / L2 — Form 8868 extension
(3, 'Tax-Exempt Organizations', 'Green Valley Nature Conservancy, a calendar-year 501(c)(3), realizes on May 1, 2026 that it cannot complete its Form 990 by the filing deadline. The organization files Form 8868 requesting additional time. What extension is available?', '["A 3-month automatic extension to August 15, 2026", "A 90-day extension to August 13, 2026", "No extension is available for Form 990 filings", "An automatic 6-month extension to November 15, 2026"]'::jsonb, 3, 'Under IRC Section 6081 and Form 8868 instructions, tax-exempt organizations may obtain an automatic 6-month extension for filing Form 990. For a calendar-year organization with an original deadline of May 15, 2026, the extended deadline is November 15, 2026. Unlike choice A, the extension period is 6 months, not 3 months — the IRS streamlined the extension process to a single 6-month period.', 'medium', 2),

-- Q25: medium / L3 — Regularly carried on test
(3, 'Tax-Exempt Organizations', 'Lakewood Symphony Orchestra, a 501(c)(3), sells advertising in its annual concert program book each year during a two-week period. A local taxable advertising company sells similar advertising year-round. The symphony''s advertising revenue is $35,000. Apply the ''regularly carried on'' element of the UBIT three-part test to determine whether this revenue is subject to UBIT.', '["Not subject to UBIT because the two-week selling period is not conducted with a frequency and continuity comparable to commercial activity", "Subject to UBIT because any advertising sales constitute a trade or business", "Not subject to UBIT because the total revenue is under $50,000", "Subject to UBIT because the activity is repeated annually"]'::jsonb, 0, 'Under IRC Section 512 and Treas. Reg. Section 1.513-1(c), an activity is ''regularly carried on'' if its frequency and continuity are comparable to that of a taxable commercial enterprise. A two-week annual solicitation period does not meet this standard when comparable businesses operate year-round. Unlike choice D, the fact that an activity recurs annually does not alone make it ''regularly carried on'' — the duration and frequency within each period matter.', 'medium', 3),

-- Q26: hard / L4 — Section 509(a)(2) gross receipts test
(3, 'Tax-Exempt Organizations', 'Horizon Arts Center, a 501(c)(3), receives the following support over a four-year measuring period: $180,000 from ticket sales for public performances (an exempt function), $120,000 from membership fees, $90,000 from government grants, $60,000 from investment income, and $50,000 from a single donor. The organization fails the Section 509(a)(1) one-third support test. Evaluate whether Horizon qualifies as a public charity under the Section 509(a)(2) gross receipts test.', '["No, because investment income of $60,000 exceeds one-third of the organization''s support", "No, because it already failed the Section 509(a)(1) test and cannot try another classification", "Yes, because more than one-third of support comes from exempt-function gross receipts, contributions, and membership fees", "Yes, because total revenue exceeds $500,000, satisfying the minimum revenue threshold"]'::jsonb, 2, 'Under IRC Section 509(a)(2), an organization qualifies as a public charity if it normally receives more than one-third of its support from contributions, membership fees, and gross receipts from exempt-function activities. Horizon''s qualifying support is $390,000 ($180,000 + $120,000 + $90,000) out of $500,000 total (78%), well above one-third. Unlike choice B, an organization may qualify as a public charity under any applicable provision — failure under one section does not preclude qualification under another.', 'hard', 4),

-- Q27: easy / L1 — Operational test definition
(3, 'Tax-Exempt Organizations', 'What does the operational test require for Section 501(c)(3) tax-exempt status?', '["The organization must operate exclusively for profit-generating activities", "The organization must be operated primarily for one or more exempt purposes", "The organization must have been in operation for at least five years", "The organization must operate in at least three states"]'::jsonb, 1, 'Under IRC Section 501(c)(3), the operational test requires that an organization be operated primarily for exempt purposes such as charitable, religious, educational, or scientific purposes. Unlike choice A, operating for profit-generating activities is inconsistent with exempt status — the organization must engage primarily in activities that accomplish its exempt mission.', 'easy', 1),

-- Q28: easy / L1 — Section 4940 net investment income tax rate
(3, 'Tax-Exempt Organizations', 'What is the excise tax rate on net investment income of a private foundation under Section 4940?', '["2%", "5%", "10%", "1.39%"]'::jsonb, 3, 'Under IRC Section 4940, private foundations are subject to a 1.39% excise tax on their net investment income, including interest, dividends, rents, royalties, and capital gains. Unlike choice A, the 2% rate was the original rate before the Taxpayer Certainty and Disaster Tax Relief Act of 2019 replaced the two-tier rate structure with a flat 1.39% rate.', 'easy', 1),

-- Q29: hard / L4 — Intermediate sanctions 200% additional tax
(3, 'Tax-Exempt Organizations', 'Vista Community Foundation, a 501(c)(3), pays its board chair $500,000 annually for part-time advisory services. An IRS examination determines the fair market value of these services is $120,000, establishing an excess benefit of $380,000. The board chair receives notice of the Section 4958 initial excise tax but does not correct the excess benefit within the taxable period. Analyze the total excise tax liability on the board chair, combining both the initial and additional taxes.', '["$855,000, consisting of a $95,000 initial tax (25%) plus a $760,000 additional tax (200%)", "$380,000, consisting solely of the 100% penalty for failure to correct", "$95,000, because only the 25% initial tax applies and additional taxes require a second IRS notice", "$475,000, consisting of a $95,000 initial tax plus a $380,000 correction payment"]'::jsonb, 0, 'Under IRC Section 4958, the initial excise tax on the disqualified person is 25% of the excess benefit ($380,000 x 25% = $95,000). If not corrected within the taxable period, an additional 200% tax applies ($380,000 x 200% = $760,000), for a total of $855,000. Unlike choice D, the 200% additional tax is a separate penalty — it is not the same as the correction payment, which would require returning the excess benefit to the organization.', 'hard', 4),

-- Q30: easy / L1 — Form 990 Schedule B contributors
(3, 'Tax-Exempt Organizations', 'Which Form 990 schedule reports information about an organization''s significant contributors?', '["Schedule A — Public Charity Status and Public Support", "Schedule B — Schedule of Contributors", "Schedule J — Compensation Information", "Schedule O — Supplemental Information"]'::jsonb, 1, 'Under IRC Section 6033, Schedule B of Form 990 is the Schedule of Contributors, reporting information about donors who contribute $5,000 or more (or 2% of total contributions, whichever is greater). This schedule is confidential and not publicly disclosed. Unlike Schedule A, which reports an organization''s public charity classification and support test calculations, Schedule B focuses specifically on individual contributor information.', 'easy', 1)
;

COMMIT;
